poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le filet en médaillons épais et fais-les dorer dans le beurre 3 min de chaque côté.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute les échalotes, puis le vin, et laisse réduire 2 min.","timer":{"label":"Cuisson","min":2}},{"text":"Ajoute la crème et la moutarde, couvre et cuis 8 min.","timer":{"label":"Cuisson","min":8}}]},{"title":"Porc au caramel","intro":"Des morceaux de porc fondants, laqués dans un caramel au nuoc-mâm.","minutes":60,"calories":560,"difficulty":"Moyen","imageSearch":"vietnamese caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"échine de porc","plural":"échine de porc","qty":800,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":80,"unit":"g","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":3,"unit":"c. à s.","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":3,"unit":"gousse","have":false},{"name":"sauce soja","plural":"sauce soja","qty":2,"unit":"c. à s.","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le porc en cubes.","timer":null},{"text":"Fais un caramel avec le sucre et 2 c. à s. d'eau, jusqu'à ce qu'il soit ambré.","timer":{"label":"Caramel","min":5}},{"text":"Ajoute le porc, les oignons émincés et l'ail, et mélange bien.","timer":null},{"text":"Verse le nuoc-mâm, la sauce soja et 20 cl d'eau, et laisse mijoter 45 min jusqu'à ce que la sauce soit sirupeuse.","timer":{"label":"Mijotage","min":45}}]},{"title":"Rôti de porc à la moutarde","intro":"Un rôti tout doux, avec une sauce moutarde à la crème.","minutes":80,"calories":580,"difficulty":"Facile","imageSearch":"pork roast mustard sauce","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"