min.","timer":{"label":"Poêle","min":5}}]},{"title":"Filet mignon au miel et au romarin","intro":"Un filet mignon laqué au miel, juteux et parfumé.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"honey roasted pork tenderloin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":2,"unit":"","have":false},{"name":"miel","plural":"miel","qty":2,"unit":"c. à s.","have":false},{"name":"romarin","plural":"romarin","qty":null,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais dorer les filets entiers dans l'huile sur toutes les faces.","timer":null},{"text":"Badigeonne-les de miel, ajoute l'ail et le romarin, sale et poivre.","timer":null},{"text":"Enfourne 20 min, puis laisse reposer 5 min avant de trancher.","timer":{"label":"Four","min":20}}]},{"title":"Filet mignon aux champignons","intro":"Le filet mignon en sauce crémeuse aux champignons.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"pork tenderloin mushroom sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":2,"unit":"","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"échalote","plural":"échalotes","qty":1,"unit":"","have":false},{"name":"beurre","plural":"beurres","qty":20,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer les médaillons dans le beurre 3 min de chaque côté. Réserve.","timer":{"label":"Poêle","min":6}},{"text":"Fais revenir l'échalote et les champignons 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Ajoute la crème et la viande, et laisse mijoter 6 min.","timer":{"label":"Mijotage","min":6}}]},{"title":"Colombo de porc","intro":"Le colombo antillais au porc, mijoté longuement.","minutes":90,"calories":560,"difficulty":"Facile","imageSearch":"pork colombo","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette antillaise","serves":4,"items":[{"name":"épaule de porc","plural":"épaules de porc","qty":800,"unit":"g","have":false},{"name":"poudre de colombo","plural":"poudre de colombo","qty":2,"unit":"c. à s.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":3,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":3,"unit":"gousse","have":false}],"steps":[{"text":"Coupe le porc en cubes et fais-le dorer avec les oignons.","timer":{"label":"Cuisson","min":8}},{"text":"Ajoute l'ail, le colombo, puis 50 cl d'eau.","timer":null},{"text":"Laisse mijoter 45 min.","timer":{"label":"Cuisson","min":45}},{"text":"Ajoute les pommes de terre et l'aubergine en morceaux et laisse 25 min.","timer":{"label":"Cuisson","min":25}}]},{"title":"Gyros","intro":"Le sandwich grec, au porc et au tzatziki.","minutes":35,"calories":640,"difficulty":"Facile","imageSearch":"pork gyros pita tzatziki","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat grec","serves":4,"items":[{"name":"échine de porc","plural":"échine de porc","qty":600,"unit":"g","have":false},{"name":"pain pita","plural":"pains pita","qty":4,"unit":"","have":false},{"name":"origan","plural":"origan","qty":1,"unit":"c. à c.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"yaourt grec","plural":"yaourts grecs","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Coupe le porc en fines lanières et mélange-le avec l'huile, l'origan, le paprika et le sel.","timer":null},{"text":"Fais-le griller 8 min à feu vif.","timer":{"label":"Poêle","min":8}},{"text":"Râpe le concombre, presse-le et mélange-le avec le yaourt et l'ail.","timer":null},{"text":"Garnis les pitas de viande, de tomate, d'oignon et de tzatziki.","timer":null}]},{"title":"Rôti de porc au miel et aux épices","intro":"Un rôti laqué, sucré-salé et parfumé.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"honey glazed pork roast","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"miel","plural":"miel","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"quatre-épices","plural":"quatre-épices","qty":1,"unit":"c. à c.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Mélange le miel, la sauce soja, l'ail haché et les épices.","timer":null},{"text":"Mets le rôti dans un plat avec les pommes de terre en morceaux et badigeonne-le de sauce.","timer":null},{"text":"Enfourne 1 h en arrosant toutes les 20 min.","timer":{"label":"Four","min":60}}]},{"title":"Porc aigre-doux","intro":"Le classique des restaurants chinois, au porc.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"sweet and sour pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":3,"unit":"c. à s.","have":false},{"name":"ananas","plural":"ananas","qty":200,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare la sauce : ketchup, vinaigre, sucre et 10 cl d'eau.","timer":null},{"text":"Coupe le porc en dés, enrobe-le de fécule et fais-le dorer 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter le poivron, l'oignon et l'ananas 4 min.","timer":{"label":"Wok","min":4}},{"text":"Ajoute la sauce et le porc, et laisse épaissir 2 min.","timer":{"label":"Wok","min":2}}]}]$r$::jsonb, 'claude')
