insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('jambon', 'jambon', array[]::text[], 'list', $r$[{"title":"Endives au jambon","intro":"Des endives fondantes roulées dans du jambon, gratinées sous une béchamel.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"endives ham gratin bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min à la vapeur ou dans l'eau, puis presse-les bien pour les égoutter.","timer":{"label":"Cuisson","min":20}},{"text":"Fais une béchamel : beurre fondu, farine, puis lait en fouettant 5 min. Ajoute muscade, sel et poivre.","timer":{"label":"Béchamel","min":5}},{"text":"Préchauffe le four à 200 °C. Roule chaque endive dans une tranche de jambon et range-les dans un plat.","timer":null},{"text":"Nappe de béchamel et parsème d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true},{"title":"Calzone","intro":"La pizza pliée en chausson, garnie de jambon, mozzarella, champignons et œuf.","minutes":100,"calories":700,"difficulty":"Moyen","imageSearch":"calzone","veg":false,"oven":true,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"farine","plural":"farines","q