Choucroute express","intro":"La choucroute pour un soir de semaine.","minutes":35,"calories":700,"difficulty":"Facile","imageSearch":"quick sauerkraut sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"choucroute cuite","plural":"choucroute cuite","qty":1000,"unit":"g","have":false},{"name":"saucisse de Strasbourg","plural":"saucisses de Strasbourg","qty":4,"unit":"","have":false},{"name":"saucisse fumée","plural":"saucisses fumées","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":15,"unit":"cl","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais chauffer la choucroute avec le vin blanc et les saucisses fumées 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les saucisses de Strasbourg 8 min avant la fin et sers avec les pommes de terre.","timer":{"label":"Cuisson","min":8}}]},{"title":"Cassoulet express","intro":"Le goût du cassoulet sans y passer la journée.","minutes":45,"calories":780,"difficulty":"Facile","imageSearch":"quick cassoulet beans","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Sud-Ouest","serves":4,"items":[{"name":"haricot blanc","plural":"haricots blancs","qty":800,"unit":"g","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"chapelure","plural":"chapelure","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural"