insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('oeuf', 'oeuf', array[]::text[], 'list', $r$[{"title":"Accras de morue","intro":"Les beignets antillais à la morue, relevés au piment et à la cive.","minutes":120,"calories":280,"difficulty":"Moyen","imageSearch":"salt cod fritters accras","veg":false,"oven":false,"cold":false,"missing":"","origin":"Recette antillaise","serves":4,"items":[{"name":"morue salée","plural":"morue salée","qty":250,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":1,"unit":"","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"ail","plural":"ail","qty":2,"unit":"gousse","have":false},{"name":"piment","plural":"piments","qty":1,"unit":"","have":false},{"name":"levure chimique","plural":"levure chimique","qty":1,"unit":"c. à c.","have":false},{"name":"huile de friture","plural":"huile de friture","qty":100,"unit":"cl","have":false}],"steps":[{"text":"Fais dessaler la morue 1 nuit dans l'eau froide en changeant l'eau.","timer":null},{"text":"Poche-la 10 min dans de l'eau frémissante, puis émiette-la.","timer":{"label":"Cuisson","min":10}},{"text":"Mélange la farine, la levure, l'œuf et 20 cl d'eau, puis ajoute la morue, l'oignon, l'ail et le piment hachés.","timer":null},{"text":"Laisse reposer 1 h.","timer":{"label":"Repos","min":60}},{"text":"Fais frire des petites cuillerées de pâte 3 min dans l'huile chaude.","timer":{"label":"Friture","min":3}}]},{"title":"Nuggets de poulet maison","intro":"Des morceaux de poulet panés et croustillants, bien meilleurs que ceux du commerce.","minutes":25,"calories":450,"difficulty":"Facile","imageSearch":"homemade chicken nuggets","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"blanc de poulet","plural":"blancs de poulet","qty":4,"unit":"","have":false},{"name":"chapelure","plural":"chapelu