me":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"sucre roux","plural":"sucre roux","qty":1,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais tremper les nouilles 10 min dans l'eau chaude, puis égoutte-les.","timer":{"label":"Trempage","min":10}},{"text":"Fais sauter le poulet en lanières 5 min dans l'huile.","timer":{"label":"Wok","min":5}},{"text":"Pousse-le sur le côté et brouille les œufs.","timer":null},{"text":"Ajoute les nouilles, la sauce soja, le sucre et le jus d'un citron vert, et fais sauter 3 min.","timer":{"label":"Wok","min":3}},{"text":"Ajoute les pousses de soja et les oignons, et sers avec les cacahuètes concassées et le citron vert.","timer":null}]},{"title":"Bo bun au bœuf","intro":"Des vermicelles de riz, du bœuf sauté à la citronnelle, des crudités et des herbes, avec la sauce nuoc-mâm.","minutes":30,"calories":520,"difficulty":"Moyen","imageSearch":"bo bun beef vermicelli bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"vermicelle de riz","plural":"vermicelles de riz","qty":200,"unit":"g","have":false},{"name":"bœuf à griller","plural":"bœuf à griller","qty":400,"unit":"g","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"concombre","plural":"concombres","qty":0.5,"unit":"","have":false},{"name":"laitue","plural":"laitues","qty":0.5,"unit":"","have":false},{"name":"menthe","plural":"menthe","qty":null,"unit":"","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"cacahuète","plural":"cacahuètes","qty":40,"unit":"g","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":4,"unit":"c. à s.","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"citronnelle","plural":"citronnelle","qty":1,"unit":"","have":false}],"steps":[{"text":"Prépare la sauce : nuoc-mâm, jus des citrons verts, sucre et 8 c. à s. d'eau.","timer":null},{"text":"Fais cuire les vermicelles 3 min, rince-les à l'eau froide.","timer":{"label":"Cuisson","min":3}},{"text":"Fais sauter le bœuf en lanières avec la citronnelle hachée 3 min à feu vif.","timer":{"label":"Wok","min":3}},{"text":"Dans des bols, mets la salade, les vermicelles, les crudités en julienne, le bœuf, les herbes et les cacahuètes, puis la sauce.","timer":null}]},{"title":"Riz cantonais","intro":"Le riz sauté du traiteur : jambon, œufs, petits pois et sauce soja.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"cantonese fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"riz cuit","plural":"riz cuit","qty":600,"unit":"g","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Bats les œufs et fais-les cuire en omelette fine dans 1 c. à s. d'huile, puis coupe-la en lanières.","timer":{"label":"Poêle","min":2}},{"text":"Fais sauter le riz froid dans le reste d'huile 5 min à feu vif.","timer":{"label":"Wok","min":5}},{"text":"Ajoute le jambon, les petits pois et les oignons 3 min.","timer":{"label":"Wok","min":3}},{"text":"Ajoute la sauce soja et l'omelette, et mélange.","timer":null}],"kids":true},{"title":"Rouleaux de printemps aux crevettes","intro":"Des galettes de riz roulées avec crevettes, vermicelles, salade et menthe, sans cuisson.","minutes":30,"calories":220,"difficulty":"Moyen","imageSearch":"fresh spring rolls shrimp","veg":false,"oven":false,"cold":true,"missing":"","origin":"Recette vietnamienne","serves":4,"items":[{"name":"galettes de riz","plural":"galettes de riz","qty":8,"unit":"","have":false},{"name":"crevette cuite","plural":"crevettes cuites","qty":16,"unit":"","have":false},{"name":"vermicelles de riz","plural":"vermicelles de riz","qty":80,"unit":"g","have":false},{"name":"salade verte","plural":"salade verte","qty":1,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":1,"unit":"","have":false},{"name":"menthe fraîche","plural":"menthe fraîche","qty":null,"unit":"","have":false},{"name":"sauce hoisin","plural":"sauce hoisin","qty":4,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais tremper les vermicelles 5 min dans l'eau chaude et égoutte-les.","timer":null},{"text":"Râpe la carotte et décortique les crevettes.","timer":null},{"text":"Trempe une galette quelques secondes dans l'eau tiède et pose-la à plat.","timer":null},{"text":"Garnis de salade, vermicelles, carotte et menthe, puis de 2 crevettes coupées en deux.","timer":null},{"text":"Replie les côtés et roule serré. Sers avec la sauce hoisin.","timer":null}]},{"title":"Salade de riz au thon","intro":"Le riz froid avec thon, tomates, maïs, poivron et œufs durs.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"rice salad tuna","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"riz","plural":"riz","qty":250,"unit":"g","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":280,"unit":"g","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"maïs","plural":"maïs","qty":140,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouge